<script setup lang="ts">
import {ref} from 'vue';import {useMerchantStore} from '@/stores/merchant';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {managementGo} from '@/shared/management';import type {ManagementResource,PaymentMerchant} from '@/api/management-types';
const {t}=useI18n();const merchant=useMerchantStore();const selectedEntity=ref<ManagementResource|null>(null);const m=ref(''),type=ref('STORE');const rows=ref<ManagementResource[]>([]);const merchants=ref<PaymentMerchant[]>([]);const next=ref<string|null>(null);const failed=ref(false);const busy=ref(false);const selecting=ref(false);
async function load(more=false){if(busy.value)return;busy.value=true;failed.value=false;try{const p=type.value==='STORE'?await api.mManagementStores(m.value,{cursor:more?next.value||undefined:undefined}):await api.mManagementEntities(m.value,more?next.value||undefined:undefined);rows.value=more?[...rows.value,...p.items]:p.items;next.value=p.nextCursor}catch{failed.value=true}finally{busy.value=false}}
async function pick(entity:ManagementResource){if(busy.value)return;busy.value=true;try{selectedEntity.value=entity;merchants.value=await api.mPaymentMerchantCandidates(entity.entityNo!,m.value);selecting.value=true}catch{failed.value=true}finally{busy.value=false}}
onLoad(q=>{m.value=q?.m||'';type.value=q?.type||'STORE'});onShow(()=>load());
</script>
<template><sh-scaffold :title="t(type==='STORE'?'management.stores':type==='ENTITY'?'management.entities':'management.paymentMerchants')"><view v-if="failed" class="sh-card" @tap="load()">{{t('management.retry')}}</view>
 <view v-for="row in rows" :key="row.resourceNo" class="sh-card sh-row sh-row--between" @tap="type==='STORE'?managementGo('store_brand',{m,s:row.storeNo}):type==='PAYMENT_MERCHANT'?pick(row):row.canManageLegacy?managementGo('entityDetail',{entityNo:row.entityNo}):undefined"><text class="txt-title">{{row.name}}</text><text class="sh-chip">{{t('management.state.'+row.status)}}</text><sh-go v-if="type!=='ENTITY'||row.canManageLegacy"/></view>
 <sh-empty v-if="!busy&&!failed&&!rows.length" :text="t('management.empty')"/><view v-if="next" class="sh-btn sh-btn--soft" @tap="load(true)">{{t('management.more')}}</view>
 <sh-sheet :visible="selecting" :title="t('management.paymentMerchants')" @close="selecting=false"><view v-for="row in merchants" :key="row.payMerchantNo" class="sh-cell"><text>{{row.payChannel}}</text><view class="txt-sub sh-muted">{{row.payMethods.join(' / ')}}</view></view><sh-empty v-if="!merchants.length" bare :text="t('management.empty')"/><template v-if="selectedEntity?.canManageLegacy" #foot><view class="sh-btn" @tap="managementGo('payment',{entityNo:selectedEntity.entityNo})">{{t('management.managePayment')}}</view></template></sh-sheet>
 <sh-actionbar v-if="type==='ENTITY'&&merchant.can('biz:store:admin')"><view class="sh-btn" @tap="managementGo('apply')">{{t('management.createEntity')}}</view></sh-actionbar></sh-scaffold></template>
